import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int Q = Integer.parseInt(line.trim());StringBuilder sb = new StringBuilder();for (int i = 0; i < Q; i++) {StringTokenizer st = new StringTokenizer(br.readLine());int L = Integer.parseInt(st.nextToken());int R = Integer.parseInt(st.nextToken());int X = Integer.parseInt(st.nextToken());sb.append(countSetBits(R, X) - countSetBits(L - 1, X)).append("\n");}System.out.print(sb.toString());}private static long countSetBits(int n, int x) {if (n <= 0) return 0;long period = 1L << x;long halfPeriod = 1L << (x - 1);long fullPeriods = (n + 1) / period;long count = fullPeriods * halfPeriod;long remainder = (n + 1) % period;if (remainder > halfPeriod) {count += (remainder - halfPeriod);}return count;}}